import{_ as a,o as t,c as d,a2 as s}from"./chunks/framework.Cu3jFwFD.js";const p=JSON.parse('{"title":"Damage and repair","description":"","frontmatter":{},"headers":[],"relativePath":"features/damage-and-repair/design.md","filePath":"features/damage-and-repair/design.md","lastUpdated":1794908281000}'),r={name:"features/damage-and-repair/design.md"};function i(n,e,o,h,l,c){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="damage-and-repair" tabindex="-1">Damage and repair <a class="header-anchor" href="#damage-and-repair" aria-label="Permalink to &quot;Damage and repair&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>The van has 10 visible hit points. Crashes, lightning and failed Chance deliveries take them away, and they stay lost from one day to the next until the player pays to repair them in the Garage. At 0 HP the van is wrecked and the day fails, but the run goes on. Every source of damage is visible, so a loss never feels random. Serves <strong>Bro thinks he&#39;s smart</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li>Max HP is 10. HP carries from day to day; it never refills by itself. (<a class="decision-ref" href="/hex-gdd/GDD#d-026">D‑026</a>)</li><li>Each source of damage removes a fixed amount of HP: map hazards (crash, lightning, big strike, boundary) are listed in <a href="./../hazards/design">hazards</a>; a failed Chance delivery in <a href="./../packages/design">packages</a>. The van flashes red and the camera reacts on every hit.</li><li><strong>Damage states:</strong> above 6 HP clean, 4–6 dented (white smoke), 3 or less badly damaged (black smoke). Each state lowers the van&#39;s top speed (<a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>): dented −10%, badly damaged −25%. The cut stacks with upgrades by multiplication and lifts as soon as HP rises (repair).</li><li>A health bar is always visible on the HUD. The money cost of repair appears only in the Garage.</li><li><strong>Repair</strong> is optional and paid in the Garage with cash: one button restores all missing HP for the repair price. Cost is rounded up and reduced by upgrades (<a href="./../upgrades/design">upgrades</a>).</li><li><strong>Wreck:</strong> at 0 HP controls lock, time slows, the van explodes, and a pop-up explains the fine. The day is FAILED: overtime money earned that day is forfeited, only half of the remaining income is kept, and the van is restored to full HP for free for the next day.</li><li>The only hazard that wrecks the van outright is <code>boundary</code> (<a href="./../hazards/design">hazards</a>). Late overtime ends in a wreck through ever-heavier lightning, not a single strike (<a href="./../day-cycle-and-storm/design">day-cycle-and-storm</a>).</li><li>The end-of-day report shows only the van&#39;s HP at the end of the day, not a breakdown by source (<a class="decision-ref" href="/hex-gdd/GDD#d-038">D‑038</a>). In-shift hit feedback (flash, camera, pop-ups) is what tells the player where damage came from.</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Max HP</td><td>10</td><td>HP</td><td></td></tr><tr><td>Hazard damage</td><td>see <a href="./../hazards/design">hazards</a></td><td>HP</td><td></td></tr><tr><td>Failed Chance delivery</td><td>2 (<a class="decision-ref" href="/hex-gdd/GDD#d-035">D‑035</a>)</td><td>HP</td><td>Is the gamble still tempting at the 25% tier?</td></tr><tr><td>Repair price</td><td>30 per HP, rounded up</td><td>$ per HP</td><td>Share of cash spent on repair vs cards</td></tr><tr><td>Wreck income kept</td><td>50</td><td>%</td><td>Is a wreck painful but not a run-ender?</td></tr><tr><td>Dented / badly damaged at</td><td>6 / 3</td><td>HP</td><td></td></tr><tr><td>Top speed in dented / badly damaged state</td><td>−10 / −25 (<a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>) <mark class="tune">TUNE</mark></td><td>%</td><td>Is a damaged van slower but still able to finish a shift?</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>A hit that would take HP below 0 stops at 0 and triggers the wreck once.</li><li>Carried HP at the start of a day is at least 1 even after a wreck sequence, so the van always moves.</li><li>Repair is full or nothing (<a class="decision-ref" href="/hex-gdd/GDD#d-039">D‑039</a>): with less cash than the full price the button is disabled and shows the price.</li><li>Game over resets HP to 10.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> The 30 $/HP price is the prototype&#39;s.</li><li>Failed Chance delivery costs 2 HP, equal to a lightning strike (<a class="decision-ref" href="/hex-gdd/GDD#d-035">D‑035</a>).</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: damage states slow the van (<a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>); hazard damage moved to <a href="./../hazards/design">hazards</a> (<a class="decision-ref" href="/hex-gdd/GDD#d-080">D‑080</a>).</li><li>2026-11-17: designed. <a class="decision-ref" href="/hex-gdd/GDD#d-026">D‑026</a> (visible HP and paid repair) supersedes the hidden-damage model (<a class="decision-ref" href="/hex-gdd/GDD#d-015">D‑015</a>: &quot;HP removed, 3 states and a surprise bill&quot;); <a class="decision-ref" href="/hex-gdd/GDD#d-027">D‑027</a> adds scam damage.</li></ul>',13)])])}const f=a(r,[["render",i]]);export{p as __pageData,f as default};
